#include "fiber.hpp"
namespace fiber {
const std::vector<CharacterDef>& characters(){ static const std::vector<CharacterDef> data={
{"mira","Мира Меловая","Купчиха","Её отец научил её считать долги раньше, чем буквы. Она держит в памяти имена тех, кто однажды не вернул сдачу.","Иногда Мира продаёт товары по себестоимости. Об этом она никому не признаётся.",{"У меня даже пауза в разговоре стоит денег. Тебе сделать скидку?","Если пришёл торговаться, сначала скажи, чего боишься потерять.","Я знаю цену каждой вещи. Кроме доверия, с ним вечно ошибаюсь."},"Договор без свидетеля живёт до первого дождя.",4,1,0,2,2,0.38f,0.74f,0.77f,0.43f,0.08f,54,{5,4,6,0},3},
{"varen","Варрен Рок","Капитан дозора","После пожара он потерял напарника. Теперь записывает не только преступления, но и собственные ошибки.","Варрен знает, кто продаёт ключи от северных ворот, но пока не имеет доказательств.",{"Не принимай отсутствие наручников за доверие.","У колокола хорошая память. У людей гораздо хуже.","В этом городе закон на двух ногах. Одни мои, другие пока целы."},"Показания важнее слуха. Но слухи приводят к показаниям.",1,3,3,0,1,0.88f,0.83f,0.13f,0.40f,-0.03f,31,{7,0,0,0},2},
{"lariel","Лариэль","Странница с перевала","Носит чужую карту и не рассказывает, кого оставила за перевалом. Не терпит пустой жестокости.","Лариэль по ночам оставляет еду у тропы для людей, которым некуда вернуться.",{"Твои следы говорят больше, чем твой голос.","В лесу легко потеряться. Гораздо труднее вернуться тем же человеком.","Птицы замолкают, когда кто-то врёт. Сейчас они ещё поют."},"Я не стреляю ради забавы. И не забываю тех, кто стреляет.",0,4,4,2,6,0.91f,0.91f,0.11f,0.57f,0.04f,19,{7,3,0,0},2},
{"nell","Нель Бесследный","Сборщик чужих ключей","Нель никогда не называет работу преступлением, пока за неё кто-нибудь платит.","Боится глубоких колодцев после детства у соляных шахт.",{"Если ты здесь по делу, говори. Если по совести, дверь там.","Я не вор. Я ускоряю оборот собственности.","О, ещё одно честное лицо. Здесь такие долго не сохраняются."},"У каждого замка есть ключ. И у каждой добродетели цена.",2,2,6,5,4,0.51f,0.76f,0.71f,0.29f,0.00f,25,{11,4,0,0},2},
{"elina","Элина из Дома золы","Хранительница обетов","Её школа сгорела вместе с архивом. С тех пор она различает огонь очищения и огонь ненависти.","Под алтарём хранится ключ от комнаты, существование которой орден отрицает.",{"Не все раны видны. Некоторые оставляют только тишину.","Зола умеет хранить форму сгоревших вещей. И имена тоже.","Не торопись клясться. Мир плохо переносит пустые обеты."},"Милосердие не делает ложь истиной.",3,7,7,0,9,0.56f,0.70f,0.05f,0.82f,0.02f,13,{2,5,0,0},2},
{"eirin","Эйрин Тихая","Хозяйка трактира","Ей рассказывают больше, чем исповедникам. Она никогда не выдаёт тайну без причины.","Каждую пятницу оставляет на пороге бесплатную похлёбку, хотя притворяется, что это ошибка кухни.",{"Сядь ближе к огню. Дорога у тебя в глазах.","Усталость лучше оставлять на пороге, как мокрые сапоги.","Здесь можно молчать сколько угодно. За молчание денег не беру."},"Не всё, что сломано, нужно выбрасывать.",0,2,2,2,8,0.41f,0.85f,0.36f,0.90f,0.09f,33,{0,4,0,0},2},
{"grinn","Гринн Третий Гвоздь","Портовый грузчик","Три гвоздя в его прозвище принадлежат трём покойным капитанам, и это никого не успокаивает.","Пишет стихи на обороте долговых расписок.",{"Дело говори. Река ждать не станет.","Слова плохо плавают. Потому я их не люблю.","Хочешь спорить? Купи сначала что-нибудь крепче воздуха."},"Мокрая верёвка честнее сухой клятвы.",2,5,5,2,0,0.79f,0.39f,0.64f,0.23f,-0.06f,14,{5,0,0,0},2},
{"silva","Сильва Десятница","Корабельная оценщица","Покупает корабли, которые другие считают обречёнными, и умеет находить полезное в обломках.","Хранит расписку должника, которого давно простила.",{"Река подорожала. Даже когда она стоит на месте.","Вещь стоит столько, сколько её готовы унести.","Бумаги чисты. Люди обычно не очень."},"Я доверяю весам, но не тем, кто на них смотрит.",4,5,1,2,2,0.59f,0.74f,0.64f,0.31f,0.03f,41,{6,7,0,0},2},
{"thorn","Торн Железорукий","Кузнец","Потерял слух на одно ухо и приобрёл удивительную способность угадывать ложь по лицам.","Выковал клинок для человека, которого потом лично же остановил.",{"Чего хотел? Железо не станет мягче от беседы.","Работа есть работа. Остальное пусть решают священники.","Искры лгут меньше людей."},"Хорошая сталь гнётся прежде, чем ломается.",4,1,0,2,2,0.78f,0.60f,0.32f,0.52f,0.02f,21,{0,5,0,0},2},
{"ilia","Илия Певчая","Послушница","Она поёт для погибших по именам. Последнее имя в её списке пока не написано.","Не верит в пророчество, которое ежедневно читает перед прихожанами.",{"Мне кажется, я слышала твои шаги раньше.","Иногда молитва не помогает. Но молчать ещё тяжелее.","Сегодня колокол снова не звонил. Это нехорошо."},"Когда нечего сказать, я просто остаюсь рядом.",3,7,7,2,9,0.27f,0.56f,0.06f,0.94f,0.14f,11,{0,2,0,0},2},
{"corvin","Корвин Дальний","Старший дозорный","Охраняет ворота восемь лет и уверен, что большинство неприятностей входит без всякого разрешения.","Заучивает чужие рассказы, чтобы не думать о собственной семье.",{"Стой в свете фонаря. Я должен видеть руки.","На воротах сегодня ничего хорошего. Как обычно.","Если заметишь свежую кровь на камнях, сообщи, не разглядывай."},"Нарушение остаётся нарушением, даже если его красиво объяснили.",1,3,3,2,1,0.77f,0.81f,0.19f,0.28f,-0.11f,18,{7,0,0,0},2},
{"letta","Летта Чернильница","Городская писарь","Записывает имена прибывших в Предел, но однажды обнаружила собственное имя в списке умерших.","Украла страницу из налоговой книги, чтобы защитить сироту.",{"Твоё имя? Только не выдумывай третье за день.","Мне нужна правда. Даже плохо написанная.","Здесь сотни записей, и каждая думает, что единственная."},"То, что не записано, слишком легко исчезает.",1,0,0,7,9,0.31f,0.71f,0.15f,0.47f,0.00f,29,{10,6,7,0},3},
{"brann","Бранн Перевозчик","Хозяин лодки","Помнит шесть больших половодий. Седьмое ожидает без всякого восторга.","Каждый год переправляет через реку один пустой гроб.",{"Не стой у края, доски нынче хуже памяти.","Река вчера принесла чужой башмак. И никаких хороших новостей.","Лодка старая, но разговоры выдерживает."},"На воде неважно, кто ты. Важно, умеешь ли грести.",0,5,5,2,0,0.65f,0.42f,0.35f,0.73f,0.06f,15,{4,0,0,0},2},
{"owl","Старая Сова","Травница","Лечит хвори странными настоями и утверждает, что каждому дереву нужно дать имя.","Знает тайный путь от часовни к руинам.",{"Слышишь, как земля ворочается под корнями?","Ты пришёл с чужим шумом за спиной.","Не все грибы растут из мха. Некоторые из обещаний."},"У леса нет часов. Зато есть память.",3,4,4,7,3,0.40f,0.96f,0.07f,0.58f,0.01f,9,{2,3,0,0},2},
{"flet","Флетт Клин","Скупщик секретов","Его никто не видел приходящим. Зато все замечают, когда он уходит с их вещами.","Панически боится звона серебряных колокольчиков.",{"Какой удивительно громкий шаг для человека с секретами.","Скажи правду, я всё равно сочиню интереснее.","В руинах нет пустых комнат. Есть только хорошо спрятанные вещи."},"Чужая тайна становится моей, когда я узнаю её раньше остальных.",2,6,6,5,4,0.62f,0.88f,0.86f,0.13f,-0.16f,47,{11,6,12,0},3},
{"emery","Эмери Полевой","Лекарь","Пытается лечить всех, даже тех, кто только что пытался ударить его самого.","Иногда подделывает рецепты, чтобы бедняки получали лекарства бесплатно.",{"Есть боль, о которой не спросишь у врача. Но я всё же попробую.","Ты выглядишь живым. Продолжим поддерживать эту приятную случайность.","Настой вереска закончился. Пациенты об этом ещё не знают."},"Пока дышишь, выбирать не поздно.",0,7,0,2,3,0.37f,0.87f,0.04f,0.92f,0.11f,23,{2,0,0,0},2},
{"kad","Кад Каменщик","Мастер улиц","Сам чинил площадь после пожара. Теперь замечает каждую трещину в чужих рассказах.","Под самым большим камнем площади спрятал письмо сыну.",{"Мостовую чинить некому, зато спорить мастеров хватает.","Шагай осторожнее. Камень под тобой ещё не улёгся.","Будет время, подсоби с плитой. Она не любит одиночества."},"Камень терпелив, но даже ему бывает достаточно.",0,0,0,2,7,0.60f,0.38f,0.23f,0.78f,0.12f,15,{0,3,0,0},2},
{"fenna","Фенна Излом","Охотница","Может пройти ночью через чащу, не сломав ветки. Почти всегда возвращается с плохой новостью.","Однажды отпустила опасного зверя, потому что узнала в нём человеческий страх.",{"Ты слишком громко дышишь для леса.","Следы на тропе вчера были свежими. Сегодня кто-то их смыл.","Держи глаза открытыми, а рот закрытым. Лучшее правило."},"Не каждый, кто бежит, виноват.",0,4,4,2,6,0.87f,0.95f,0.15f,0.37f,-0.02f,16,{3,7,0,0},2},
{"olven","Олвен Быстрая","Посыльная","Выросла на дороге между двумя городами и боится жить на одном месте.","Умеет читать печати, не вскрывая писем.",{"Если ты за письмом, оно уже почти ушло.","Я могу доставить что угодно. Кроме хорошего настроения капитана.","Не хочешь никуда бежать? Тогда расскажи, почему."},"Плохие новости бегают быстрее хороших, потому я и тренируюсь.",4,1,0,5,2,0.55f,0.63f,0.40f,0.58f,0.15f,18,{8,3,0,0},2},
{"ghash","Гаштай Лоскут","Уличный рассказчик","Каждую историю рассказывает трижды и с разными концовками. Никто не знает, какой была первая.","До войны Гаштай был судьёй и сам подписал свой приговор.",{"У меня есть рассказ о тебе. Только события ещё не случились.","Сегодня ветер звучит, словно старая скрипка.","Скажи, какой финал любишь: справедливый или правдивый?"},"Правда меняет форму, когда её повторяют.",0,0,2,2,0,0.24f,0.74f,0.26f,0.61f,0.08f,5,{0,7,0,0},2},
};return data;}
const char* zoneName(int n){static const char* names[]={"Площадь колокола","Торговые ряды","Трактир «Последний свет»","Сторожевая башня","Вересковая чаща","Соляная пристань","Обвалившийся архив","Часовня золы"};return names[(n%8+8)%8];}
const char* zoneLore(int n){static const char* names[]={"Колокол молчит третий день. Пахнет мокрым камнем, дымом и обещаниями, которые никто не торопится выполнять.","Лавки цепляются за кривую мостовую. Торговцы знают о чужих долгах больше, чем исповедники.","В очаге угли, под потолком паутина. Одни приходят сюда за теплом, другие за людьми, о которых лучше не спрашивать.","Железные ворота, свежие объявления о розыске и лестница, скрипящая под чужими признаниями.","Над мокрым мхом висит туман, а на тропах встречаются следы тех, кто уверяет, будто сюда не заходил.","Канаты натянуты, лодки скрежещут у свай. Река принимает всё, что ей поручают не замечать.","Между обрушенными колоннами свистит ветер. Кто-то недавно зажигал здесь свечи, хотя вход давно заброшен.","Белые ленты привязаны к мёртвому дереву. Внутри пахнет воском, горькой травой и тайной."};return names[(n%8+8)%8];}
}
